object Main {
  def main(args: Array[String]): Unit = {
    val n = scala.io.StdIn.readInt()
    val angka = scala.io.StdIn.readLine().trim.split("\\s+").map(_.toInt).toList
    val min = angka.min
    val max = angka.max
    val ganjil = angka.filter(_ % 2 != 0).sum
    println(s"$min $max $ganjil")
  }
}

